style.css:
@-moz-document url-prefix("http://"), url-prefix("https://") {
/* =========================================================
   ☁️ CLOUD AURORA — GLOBAL STREAMING SUBTITLES
   ========================================================= */

:root {
    --ca-subtitle-font:
        "Netflix Sans",
        "Helvetica Neue",
        Helvetica,
        Arial,
        sans-serif;

    --ca-subtitle-weight: 700;
    --ca-subtitle-color: #ffffff;

    --ca-subtitle-shadow:
        0 0 .18em rgba(0, 0, 0, 1),
        0 0 .34em rgba(70, 52, 81, .72);
}

/* ==========================================================================
   ☁️? CLOUD AURORA — GLOBAL STREAMING SUBTITLES
   v1.0

   Universal subtitle / closed-caption visual module.

   Designed for:
   • YouTube
   • Disney+
   • Amazon Prime Video
   • Netflix
   • Native HTML5 / WebVTT
   • Shaka Player
   • Compatible streaming players

   Design DNA:
   Netflix Sans • Clean background • Deep readable shadow • Aurora undertone

   IMPORTANT:
   This module intentionally DOES NOT force:
   • subtitle size
   • subtitle position
   • alignment
   • line-height

   Those remain controlled by each streaming platform / accessibility settings.
   ========================================================================== */


/* ##########################################################################
   01. CLOUD AURORA — SUBTITLE TOKENS
   ########################################################################## */

:root {
    --ca-subtitle-font:
        "Netflix Sans",
        "Helvetica Neue",
        Helvetica,
        Arial,
        sans-serif;

    --ca-subtitle-weight: 700;

    --ca-subtitle-color: #ffffff;

    --ca-subtitle-background: transparent;

    --ca-subtitle-shadow:
        0 0 .18em rgba(0, 0, 0, 1),
        0 0 .34em rgba(70, 52, 81, .72);

    --ca-subtitle-shadow-strong:
        0 0 .14em rgba(0, 0, 0, 1),
        0 0 .26em rgba(0, 0, 0, .94),
        0 0 .42em rgba(70, 52, 81, .66);
}


/* ##########################################################################
   02. NETFLIX SANS
   Original Cloud Aurora subtitle typeface.
   ########################################################################## */

@font-face {
    font-family: "Netflix Sans";

    font-weight: 700;
    font-style: normal;

    font-display: swap;

    src:
        url("https://assets.nflxext.com/ffe/siteui/fonts/netflix-sans/v3/NetflixSans_W_Md.woff2")
        format("woff2"),

        url("https://assets.nflxext.com/ffe/siteui/fonts/netflix-sans/v3/NetflixSans_W_Md.woff")
        format("woff");
}


/* ##########################################################################
   03. NATIVE HTML5 / WEBVTT
   Universal fallback.

   Covers websites using actual <track> caption/subtitle tracks rather than
   custom DOM overlays.
   ########################################################################## */

video::cue {
    background: transparent !important;

    color: var(--ca-subtitle-color) !important;

    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;

    text-shadow: var(--ca-subtitle-shadow) !important;
}


/* ##########################################################################
   04. YOUTUBE
   ########################################################################## */

.ytp-caption-segment {
    background: none !important;
    background-color: transparent !important;

    color: var(--ca-subtitle-color) !important;

    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;

    text-shadow: var(--ca-subtitle-shadow) !important;

    box-shadow: none !important;
}


/* Remove YouTube caption window background without changing placement. */

.ytp-caption-window-container,
.caption-window,
.ytp-caption-window-bottom,
.ytp-caption-window-rollup {
    background: transparent !important;
}


/* ##########################################################################
   05. DISNEY+
   DSS = Disney Streaming Services subtitle renderer.
   ########################################################################## */

span.dss-subtitle-renderer-cue,
.dss-subtitle-renderer-cue {
    background: transparent !important;
    background-color: transparent !important;

    color: var(--ca-subtitle-color) !important;

    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;

    text-shadow: var(--ca-subtitle-shadow) !important;

    box-shadow: none !important;
}


/* Disney subtitle line */

span.dss-subtitle-renderer-line,
.dss-subtitle-renderer-line {
    background: transparent !important;
    background-color: transparent !important;

    color: inherit !important;

    font-family: inherit !important;

    box-shadow: none !important;
}


/* Disney subtitle cue/window backdrop */

.dss-subtitle-renderer-cue-window {
    background: transparent !important;
    background-color: transparent !important;

    box-shadow: none !important;
}


/* ##########################################################################
   06. AMAZON PRIME VIDEO
   Prime currently uses the stable atvwebplayersdk-* player prefix.
   ########################################################################## */

.atvwebplayersdk-captions-text {
    background: transparent !important;
    background-color: transparent !important;

    color: var(--ca-subtitle-color) !important;

    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;

    text-shadow: var(--ca-subtitle-shadow) !important;

    box-shadow: none !important;
}


/*
   Prime sometimes nests caption content inside the caption element.

   We deliberately inherit styling rather than imposing layout properties.
*/

.atvwebplayersdk-captions-text > span,
.atvwebplayersdk-captions-text > div {
    background-color: transparent !important;

    color: inherit !important;

    font-family: inherit !important;
    font-weight: inherit !important;

    text-shadow: inherit !important;

    box-shadow: none !important;
}


/* ##########################################################################
   07. NETFLIX
   Netflix DOM-rendered TimedText captions.
   ########################################################################## */

.player-timedtext-text-container {
    background: transparent !important;

    color: var(--ca-subtitle-color) !important;

    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;

    text-shadow: var(--ca-subtitle-shadow) !important;

    box-shadow: none !important;
}


.player-timedtext-text-container span {
    background-color: transparent !important;

    color: var(--ca-subtitle-color) !important;

    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;

    text-shadow: var(--ca-subtitle-shadow) !important;

    box-shadow: none !important;
}


/* ##########################################################################
   08. SHAKA PLAYER
   Used by a number of HTML5 streaming implementations.
   ########################################################################## */

.shaka-text-container {
    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;
}


.shaka-text-container .shaka-text-wrapper,
.shaka-text-container .shaka-text-wrapper span {
    background-color: transparent !important;

    color: var(--ca-subtitle-color) !important;

    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;

    text-shadow: var(--ca-subtitle-shadow) !important;

    box-shadow: none !important;
}


/* ##########################################################################
   09. GENERIC PLAYER ADAPTERS
   Conservative selectors only.

   These target subtitle components belonging specifically to common video
   players rather than dangerous generic selectors such as:
       [class*="subtitle"]
       [class*="caption"]

   Those broad selectors are intentionally avoided because they can alter
   normal webpage UI.
   ########################################################################## */


/* Bitmovin Player */

.bmpui-ui-subtitle-label {
    background: transparent !important;
    background-color: transparent !important;

    color: var(--ca-subtitle-color) !important;

    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;

    text-shadow: var(--ca-subtitle-shadow) !important;

    box-shadow: none !important;
}


/* Video.js */

.vjs-text-track-display,
.vjs-text-track-cue {
    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;
}


.vjs-text-track-cue > div {
    background: transparent !important;
    background-color: transparent !important;

    color: var(--ca-subtitle-color) !important;

    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;

    text-shadow: var(--ca-subtitle-shadow) !important;

    box-shadow: none !important;
}


/* Plyr */

.plyr__captions .plyr__caption {
    background: transparent !important;
    background-color: transparent !important;

    color: var(--ca-subtitle-color) !important;

    font-family: var(--ca-subtitle-font) !important;
    font-weight: var(--ca-subtitle-weight) !important;

    text-shadow: var(--ca-subtitle-shadow) !important;

    box-shadow: none !important;
}


/* ##########################################################################
   10. YOUTUBE CC ACTIVE INDICATOR
   Ported separately because this belongs to the controls, not subtitle text.
   ########################################################################## */

.ytp-chrome-controls .ytp-button[aria-pressed="true"]::after {
    background-color: #fff8fd !important;

    box-shadow:
        0 0 6px 2px #f3b6d2,
        0 0 11px 3px rgba(207, 179, 243, .40) !important;
}


/* ##########################################################################
   11. ACCESSIBILITY / PLATFORM-SAFETY RULES

   Intentionally absent:
   font-size
   transform
   bottom
   top
   left
   right
   width
   line-height
   text-align

   The streaming service therefore retains control over:
   • subtitle scaling
   • user accessibility preferences
   • dialogue positioning
   • forced subtitles
   • speaker positioning
   • fullscreen scaling
   ########################################################################## */


/* ==========================================================================
   END — CLOUD AURORA GLOBAL STREAMING SUBTITLES v1.0
   ========================================================================== */
}
